"""Regression tests for the TimesFM-2 forecaster."""

import numpy as np
import pytest

from sktime.datasets import load_airline
from sktime.forecasting.timesfm2 import TimesFM2Forecaster
from sktime.utils.dependencies import _check_soft_dependencies

# Reference forecast was generated by calling
# transformers.TimesFm2_5ModelForPrediction directly (bypassing sktime):
#
#   from transformers import TimesFm2_5ModelForPrediction
#   import numpy as np, torch
#   from sktime.datasets import load_airline
#
#   y_train = load_airline().iloc[:-12]
#   model = TimesFm2_5ModelForPrediction.from_pretrained(
#       "google/timesfm-2.5-200m-transformers", device_map="cpu", dtype=None
#   )
#   model.eval()
#   past_values = torch.from_numpy(
#       np.expand_dims(y_train.values.astype(np.float32), axis=0)
#   ).to(model.dtype).to(model.device)
#   with torch.no_grad():
#       output = model(past_values=past_values)
#   preds = output.mean_predictions.ravel().detach().float().cpu().numpy()
#   preds[:3]  # -> [407.3865051269531, 378.2121887207031, 429.0090026855469]
_TIMESFM2_REFERENCE_HEAD = [
    407.3865051269531,
    378.2121887207031,
    429.0090026855469,
]


@pytest.mark.skipif(
    not _check_soft_dependencies("transformers[torch]>=4.52.0", severity="none"),
    reason="run test only if TimesFM2Forecaster soft dependencies are present",
)
def test_timesfm2_airline_predictions_match_transformers_reference():
    """TimesFM-2.5 predictions match the raw transformers implementation."""
    y = load_airline()
    y_train = y.iloc[:-12]
    fh = np.arange(1, 13)

    forecaster = TimesFM2Forecaster(device_map="cpu")
    y_pred = forecaster.fit(y_train, fh=fh).predict(fh=fh)

    np.testing.assert_allclose(
        y_pred.iloc[:3].to_numpy(),
        np.asarray(_TIMESFM2_REFERENCE_HEAD, dtype=np.float32),
        rtol=1e-5,
        atol=1e-4,
    )
